// WF-02 · Preparación de consultas y lectura de caché.
//
// La caché de IoC no es una optimización opcional: con el free tier de
// VirusTotal (4 peticiones/minuto), una ráfaga de alertas de la misma botnet
// agota la cuota en segundos. Cachear por IoC —no por alerta— hace que la
// segunda y sucesivas alertas de la misma campaña no consuman nada.
//
// Proveedores: AbuseIPDB, VirusTotal y CrowdSec CTI (para IPs). GreyNoise e
// IBM X-Force se retiraron del sistema — nunca llegó a haber credenciales
// operativas para ninguno de los dos (ver docs/riesgos.md).

// @blinksec-inject: lib/enrich.js

const alerta = $input.first().json;

const ipPrincipal = (alerta.artifacts?.ips ?? []).find((i) => i.direction === 'src')
  ?? (alerta.artifacts?.ips ?? [])[0];

// Se prefiere SHA256 por ser el que mejor resuelve VirusTotal.
const hashes = alerta.artifacts?.hashes ?? [];
const hashPrincipal = hashes.find((h) => h.type === 'sha256') ?? hashes[0];

const consultas = [];

if (ipPrincipal) {
  consultas.push(
    { provider: 'abuseipdb', iocType: 'ip', value: ipPrincipal.value, cacheKey: cacheKey('abuseipdb', 'ip', ipPrincipal.value) },
    { provider: 'virustotal', iocType: 'ip', value: ipPrincipal.value, cacheKey: cacheKey('virustotal', 'ip', ipPrincipal.value) },
    { provider: 'crowdsec', iocType: 'ip', value: ipPrincipal.value, cacheKey: cacheKey('crowdsec', 'ip', ipPrincipal.value) },
  );
}

if (hashPrincipal) {
  consultas.push(
    { provider: 'virustotal', iocType: 'hash', value: hashPrincipal.value, cacheKey: cacheKey('virustotal', 'hash', hashPrincipal.value) },
  );
}

return [
  {
    json: {
      alerta,
      consultas,
      enrichStartedAt: Date.now(),
      ip: ipPrincipal?.value ?? null,
      hash: hashPrincipal?.value ?? null,
    },
  },
];

// WF-02 · Agregación de respuestas.
//
// Aquí llega TODO, incluidos los proveedores que fallaron: los nodos HTTP
// tienen neverError y onError=continueRegularOutput precisamente para que un
// 503 de VirusTotal no aborte la ejecución y deje la alerta sin procesar.
//
// El resultado marca explícitamente qué se pudo consultar y qué no. Ese
// metadato es lo que permite a WF-03 aplicar el techo de puntuación y no
// contener a ciegas con información incompleta.

// @blinksec-inject: lib/enrich.js

const plan = $('Planificar consultas').first().json;
const alerta = plan.alerta;

// Mapa nodo → proveedor, para reconstruir el origen de cada respuesta.
const mapaNodos = [
  ['AbuseIPDB v2', 'abuseipdb'],
  ['VirusTotal v3', 'virustotal'],
  ['CrowdSec CTI', 'crowdsec'],
];

const proveedoresPlanificados = new Set(plan.consultas.map((c) => c.provider));
const respuestas = [];

for (const [nombreNodo, provider] of mapaNodos) {
  if (!proveedoresPlanificados.has(provider)) continue;

  let salida;
  try {
    salida = $(nombreNodo).first().json;
  } catch (e) {
    // El nodo no llegó a ejecutarse.
    respuestas.push({ provider, statusCode: 0, body: null });
    continue;
  }

  respuestas.push({
    provider,
    statusCode: salida.statusCode ?? 200,
    body: salida.body ?? salida,
  });
}

const enrichment = aggregate(respuestas);

return [
  {
    json: {
      ...alerta,
      enrichment,
      timings: {
        ingestStartedAt: alerta.ingestStartedAt,
        enrichStartedAt: plan.enrichStartedAt,
        enrichMs: Date.now() - plan.enrichStartedAt,
      },
    },
  },
];
